class LmdbGrowthUpgradeTest {

	private static final ValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI SEED_SUBJECT = VF.createIRI("urn:lmdb:growth-upgrade:seed-subject");
	private static final IRI GROWTH_PREDICATE = VF.createIRI("urn:lmdb:growth-upgrade:growth-predicate");
	private static final IRI SEED_PREDICATE = VF.createIRI("urn:lmdb:growth-upgrade:seed-predicate");
	private static final IRI REJECTED_SUBJECT = VF.createIRI("urn:lmdb:growth-upgrade:rejected-subject");
	private static final IRI REJECTED_PREDICATE = VF.createIRI("urn:lmdb:growth-upgrade:rejected-predicate");
	private static final IRI SEED_OBJECT = VF.createIRI("urn:lmdb:growth-upgrade:seed-object");
	private static final long INITIAL_MAP_BYTES = 8L * 1024L * 1024L;
	private static final int GROWTH_ROWS = 10_000;
	private static final long WAIT_SECONDS = 20L;

	@Test
	@Timeout(value = 45, unit = TimeUnit.SECONDS)
	void admittedReadCanUpgradeDuringWriterDrainAndDelaysReaderGrace(@TempDir Path dataDirectory) throws Exception {
		LmdbStore store = newStore(dataDirectory);
		store.init();
		LmdbSailStore backingStore = store.getBackingStore();
		seed(store);
		MapGrowthMetrics.Snapshot before = backingStore.growthMetricsSnapshot();

		CountDownLatch ownerReadReady = new CountDownLatch(1);
		CountDownLatch allowOwnerUpgrade = new CountDownLatch(1);
		CountDownLatch ownerUpgraded = new CountDownLatch(1);
		CountDownLatch allowOwnerCompletion = new CountDownLatch(1);
		ExecutorService ownerExecutor = Executors.newSingleThreadExecutor();
		Future<?> ownerFinished = ownerExecutor.submit(() -> {
			try (SailConnection owner = store.getConnection()) {
				try {
					try (CloseableIteration<? extends Statement> rows = beginReadSeed(owner)) {
						ownerReadReady.countDown();
						await(allowOwnerUpgrade, "the test must release the admitted readonly owner");
						// Adding the existing statement is a public no-op mutation. Its logical write intent must still
						// protect this admitted attempt until transaction completion.
						owner.addStatement(SEED_SUBJECT, SEED_PREDICATE, SEED_OBJECT);
						ownerUpgraded.countDown();
						await(allowOwnerCompletion, "the test must release the upgraded owner to finish");
						owner.commit();
					}
				} finally {
					if (owner.isActive()) {
						owner.rollback();
					}
				}
			}
			return null;
		});

		try (SailConnection graceReader = store.getConnection()) {
			try (CloseableIteration<? extends Statement> graceRows = beginReadSeed(graceReader);
					SailConnection trigger = store.getConnection()) {
				trigger.begin(IsolationLevels.SNAPSHOT);
				try {
					assertTrue(ownerReadReady.await(5, TimeUnit.SECONDS),
							"the readonly attempt must register and open its snapshot before growth closes admission");
					addGrowthStatements(trigger);
					awaitPhase(backingStore, LmdbSailStore.GrowthPhase.DRAIN_WRITERS,
							"the buffered batch must start the writer-drain phase");

					allowOwnerUpgrade.countDown();
					assertTrue(ownerUpgraded.await(5, TimeUnit.SECONDS),
							"the already-admitted readonly owner must upgrade while writers are draining");
					trigger.commit();
					assertEquals(LmdbSailStore.GrowthPhase.DRAIN_WRITERS,
							backingStore.growthMetricsSnapshot().currentPhase(),
							"the upgraded logical writer must hold the coordinator in DRAIN_WRITERS");

					allowOwnerCompletion.countDown();
					ownerFinished.get(WAIT_SECONDS, TimeUnit.SECONDS);
					awaitPhase(backingStore, LmdbSailStore.GrowthPhase.DRAIN_READERS,
							"reader grace must start only after the upgraded writer completes");
					assertTrue(backingStore.growthAdmissionClosed(),
							"reader grace must keep new attempts outside while the old snapshot is held");

					graceReader.rollback();
					graceRows.close();
					awaitGrowthReopened(store, backingStore);
					assertHasResizeSince(before, backingStore.growthMetricsSnapshot());
				} finally {
					allowOwnerUpgrade.countDown();
					allowOwnerCompletion.countDown();
					if (trigger.isActive()) {
						trigger.rollback();
					}
				}
			}
		} finally {
			allowOwnerUpgrade.countDown();
			allowOwnerCompletion.countDown();
			ownerExecutor.shutdownNow();
			try {
				assertTrue(ownerExecutor.awaitTermination(5, TimeUnit.SECONDS),
						"the admitted owner worker must finish cleanup");
			} finally {
				store.shutDown();
			}
		}
	}

	@Test
	@Timeout(value = 45, unit = TimeUnit.SECONDS)
	void upgradeAfterWriterDrainTransitionFailsPromptlyWithRetryableConflict(@TempDir Path dataDirectory)
			throws Exception {
		LmdbStore store = newStore(dataDirectory);
		store.init();
		LmdbSailStore backingStore = store.getBackingStore();
		seed(store);
		MapGrowthMetrics.Snapshot before = backingStore.growthMetricsSnapshot();

		CountDownLatch ownerReadReady = new CountDownLatch(1);
		CountDownLatch allowUpgrade = new CountDownLatch(1);
		ExecutorService ownerExecutor = Executors.newSingleThreadExecutor();
		Future<SailConflictException> rejectedUpgrade = ownerExecutor.submit(() -> {
			try (SailConnection owner = store.getConnection()) {
				try {
					try (CloseableIteration<? extends Statement> rows = beginReadSeed(owner)) {
						ownerReadReady.countDown();
						await(allowUpgrade, "the test must release the admitted readonly owner");
						SailConflictException conflict = assertThrows(SailConflictException.class,
								() -> owner.addStatement(REJECTED_SUBJECT, REJECTED_PREDICATE, SEED_OBJECT),
								"an upgrade after DRAIN_READERS begins must be retryable");
						assertTrue(owner.isActive(),
								"a rejected upgrade must leave the readonly transaction available");
						assertTrue(rows.hasNext(),
								"the rejected upgrade must preserve its pre-growth native snapshot");
						return conflict;
					}
				} finally {
					if (owner.isActive()) {
						owner.rollback();
					}
				}
			}
		});

		try (SailConnection graceReader = store.getConnection()) {
			try (CloseableIteration<? extends Statement> graceRows = beginReadSeed(graceReader);
					SailConnection trigger = store.getConnection()) {
				trigger.begin(IsolationLevels.SNAPSHOT);
				try {
					assertTrue(ownerReadReady.await(5, TimeUnit.SECONDS),
							"the readonly attempt must register and open its snapshot before growth closes admission");
					addGrowthStatements(trigger);
					awaitPhase(backingStore, LmdbSailStore.GrowthPhase.DRAIN_WRITERS,
							"the buffered batch must start the writer-drain phase");
					trigger.commit();
					awaitPhase(backingStore, LmdbSailStore.GrowthPhase.DRAIN_READERS,
							"the reader grace must be observable while an admitted snapshot remains open");

					allowUpgrade.countDown();
					SailConflictException conflict = rejectedUpgrade.get(2, TimeUnit.SECONDS);
					assertNotNull(conflict.getMessage());
					assertTrue(conflict.getMessage().toLowerCase().contains("retry"),
							"the conflict message must tell callers to retry the transaction");
					assertEquals(LmdbSailStore.GrowthPhase.DRAIN_READERS,
							backingStore.growthMetricsSnapshot().currentPhase(),
							"the held reader must keep the rejection inside the reader-grace phase");

					graceReader.rollback();
					graceRows.close();
					awaitGrowthReopened(store, backingStore);
					assertHasResizeSince(before, backingStore.growthMetricsSnapshot());
				} finally {
					allowUpgrade.countDown();
					if (trigger.isActive()) {
						trigger.rollback();
					}
				}
			}
		} finally {
			allowUpgrade.countDown();
			ownerExecutor.shutdownNow();
			try {
				assertTrue(ownerExecutor.awaitTermination(5, TimeUnit.SECONDS),
						"the rejected owner worker must finish cleanup");
			} finally {
				store.shutDown();
			}
		}
	}

	private static LmdbStore newStore(Path dataDirectory) {
		return new LmdbStore(dataDirectory.toFile(), new LmdbStoreConfig("spoc,posc")
				.setTripleDBSize(INITIAL_MAP_BYTES)
				.setValueDBSize(128L * 1024L * 1024L)
				.setAutoGrow(true)
				.setMapGrowthThreshold(0.10d)
				.setMapGrowthReadDrainTimeoutMillis(30_000L));
	}

	private static void seed(LmdbStore store) throws Exception {
		try (SailConnection connection = store.getConnection()) {
			connection.begin(IsolationLevels.SNAPSHOT);
			connection.addStatement(SEED_SUBJECT, SEED_PREDICATE, SEED_OBJECT);
			connection.commit();
		}
	}

	private static CloseableIteration<? extends Statement> beginReadSeed(SailConnection connection) throws Exception {
		connection.begin(IsolationLevels.SNAPSHOT);
		CloseableIteration<? extends Statement> rows = connection.getStatements(
				SEED_SUBJECT, SEED_PREDICATE, SEED_OBJECT, false);
		assertTrue(rows.hasNext(), "the seeded snapshot must contain its known statement");
		return rows;
	}

	private static void addGrowthStatements(SailConnection connection) throws Exception {
		for (int index = 0; index < GROWTH_ROWS; index++) {
			connection.addStatement(
					VF.createIRI("urn:lmdb:growth-upgrade:subject:" + index),
					GROWTH_PREDICATE,
					VF.createLiteral("growth-value:" + index));
		}
		// Namespaces share the authoritative TripleStore map, whose readers require the reader-grace phase.
		connection.setNamespace("growth-demand", "urn:lmdb:growth-upgrade:" + "n".repeat(2 * 1024 * 1024));
	}

	private static void await(CountDownLatch latch, String message) throws InterruptedException {
		assertTrue(latch.await(10, TimeUnit.SECONDS), message);
	}

	private static void awaitPhase(LmdbSailStore backingStore, LmdbSailStore.GrowthPhase expected, String message) {
		long deadlineNanos = System.nanoTime() + TimeUnit.SECONDS.toNanos(10);
		while (backingStore.growthMetricsSnapshot().currentPhase() != expected) {
			if (System.nanoTime() >= deadlineNanos) {
				throw new AssertionError(message + "; last phase was "
						+ backingStore.growthMetricsSnapshot().currentPhase());
			}
			Thread.yield();
		}
	}

	private static void awaitGrowthReopened(LmdbStore store, LmdbSailStore backingStore) {
		long deadlineNanos = System.nanoTime() + TimeUnit.SECONDS.toNanos(WAIT_SECONDS);
		while (backingStore.growthAdmissionClosed()
				|| backingStore.growthMetricsSnapshot().currentPhase() != LmdbSailStore.GrowthPhase.OPEN) {
			if (System.nanoTime() >= deadlineNanos) {
				throw new AssertionError("growth admission did not reopen after all active attempts were cleaned up");
			}
			Thread.yield();
		}
		try (SailConnection reopened = store.getConnection()) {
			reopened.begin(IsolationLevels.SNAPSHOT);
			reopened.rollback();
		} catch (Exception e) {
			throw new AssertionError("a fresh public transaction must be admitted after successful growth", e);
		}
	}

	private static void assertHasResizeSince(MapGrowthMetrics.Snapshot before, MapGrowthMetrics.Snapshot after) {
		assertTrue(after.tripleStoreResizes() > before.tripleStoreResizes(),
				"the coordinated episode must complete an authoritative TripleStore map resize");
		assertEquals(before.valueStoreResizes(), after.valueStoreResizes(),
				"dictionary-only growth must not supply this reader-grace stimulus");
	}
}
